const B = { minLon: 16.33, maxLat: 43.24, k: 0.72944635, scale: 1540.340149, pad: 60.0 };
export function projectIsland(lon: number, lat: number): [number, number] {
  const x = B.pad + (lon - B.minLon) * B.k * B.scale;
  const y = B.pad + (B.maxLat - lat) * B.scale;
  return [x, y];
}
